<script setup>
import Layout from '../../Components/Layout.vue'; import {useForm} from '@inertiajs/vue3'; import Icon from '../../Components/Icon.vue'
const props=defineProps({tenants:Array}); const form=useForm({tenant_id:props.tenants?.[0]?.id||'',name:'',description:'',status:'active',due_date:''}); const submit=()=>form.post('/projects')
</script>
<template><Layout><div class="page-heading"><div><span class="eyebrow">NEW DELIVERY</span><h1>Create project</h1><p>Set up a secure tenant-scoped project workspace.</p></div></div><div class="form-panel"><form @submit.prevent="submit"><div v-if="tenants?.length" class="field"><label>Client workspace</label><select v-model="form.tenant_id"><option v-for="t in tenants" :key="t.id" :value="t.id">{{t.name}}</option></select></div><div class="field"><label>Project name</label><input v-model="form.name" placeholder="e.g. Website redesign"></div><div class="field"><label>Description</label><textarea v-model="form.description" placeholder="What are you delivering?"></textarea></div><div class="form-grid"><div class="field"><label>Status</label><select v-model="form.status"><option value="active">Active</option><option value="on_hold">On hold</option><option value="completed">Completed</option></select></div><div class="field"><label>Due date</label><input v-model="form.due_date" type="date"></div></div><div class="form-actions"><button type="submit" class="primary-btn" :disabled="form.processing"><Icon name="check" :size="16"/> Create project</button></div></form></div></Layout></template>
